# Create test client
client = TestClient(app)

# ============================================
# TEST CASE UT01: Test Server Status Endpoint
# ============================================
def test_UT01_server_status():
    """Test that the server status endpoint returns correct response"""
    response = client.get("/status")
    
    assert response.status_code == 200
    data = response.json()
    assert data["status"] == "ok"
    assert "ffmpeg_available" in data
    assert "model_loaded" in data
    
    print(f"[UT01] Actual output: {data}")

