# ============================================
# TEST CASE UT04: Test Analyze with Empty Video Data
# ============================================

def test_UT04_analyze_empty_video():
    """Test video analysis with empty file data"""
    response = client.post(
        "/analyze",
        json={
            "file": "",
            "startTime": 0.0
        }
    )
    
    # The server may return 400 or 500 for empty files
    # Accept either response since both indicate failure
    assert response.status_code in [400]
    
    if response.status_code == 400:
        data = response.json()
        print(f"[UT04] Actual output: {data}")
    else:
        print(f"[UT04] Actual output: Status {response.status_code} (empty file caused internal error)")

