# ============================================
# TEST CASE UT19: Test Build Reasoning with Segments
# ============================================
def test_UT19_build_reasoning_with_segments():
    """Test reasoning builder with segment data"""
    segments = [
        {"fakeProbability": 0.85},
        {"fakeProbability": 0.88},
        {"fakeProbability": 0.90}
    ]
    
    reasoning = build_reasoning(
        is_fake=True,
        confidence=87,
        fake_prob=0.87,
        segments=segments
    )
    
    assert isinstance(reasoning, list)
    assert len(reasoning) > 0
    
    # Combine all reasoning text for checking
    full_text = " ".join(reasoning)
    assert "segments" in full_text or "consistent" in full_text
    
    print(f"[UT19] Actual output: {reasoning}")

