# TEST CASE UT24: Test Multiple Categories in Send Report
# ============================================
def test_UT24_send_report_various_categories():
    """Test sending reports with different categories"""
    categories = ["General", "Upload Video", "Record Video", 
                  "Live Overlay Detection", "App Performance", "Other"]
    
    for category in categories:
        issue_id = f"CF-{datetime.now().strftime('%Y%m%d')}-{str(hash(category))[:5]}"
        
        response = client.post(
            "/send-report",
            json={
                "issueId": issue_id,
                "category": category,
                "description": f"Test report for category: {category}",
                "device": "Pixel 6",
                "osVersion": "33",
                "appVersion": "1.0.0",
                "submittedAt": datetime.now().isoformat()
            }
        )
        
        assert response.status_code == 200
        data = response.json()
        assert data["success"] is True
    
    print(f"[UT24] Actual output: All {len(categories)} categories passed")

